func (s *Service) validateWithKzgBatchVerifier(ctx context.Context, dataColumns []blocks.RODataColumn) (pubsub.ValidationResult, error) {
	timeout := time.Duration(params.BeaconConfig().SecondsPerSlot) * time.Second  // 12s
	resChan := make(chan error)
	verificationSet := &kzgVerifier{dataColumns: dataColumns, resChan: resChan}
	s.kzgChan <- verificationSet
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	select {
	case <-ctx.Done():
		return pubsub.ValidationIgnore, ctx.Err()  // ← TIMEOUT: IGNORE not REJECT
	case err := <-resChan:
		if err != nil {
			return s.validateUnbatchedColumnsKzg(ctx, dataColumns)
		}
	}
	return pubsub.ValidationAccept, nil
}

func VerifyCellKZGProofBatch(commitmentsBytes []Bytes48, cellIndices []uint64, cells []Cell, proofsBytes []Bytes48) (bool, error) {
	ckzgCells := make([]ckzg4844.Cell, len(cells))
	for i := range cells {
		ckzgCells[i] = ckzg4844.Cell(cells[i])
	}
	return ckzg4844.VerifyCellKZGProofBatch(commitmentsBytes, cellIndices, ckzgCells, proofsBytes)
}
// Cell type is [BytesPerCell]byte — no Go-level field element range check
// BLS_MODULUS = 52435875175126190479447740508185965837690552500527637822603658699938581184513
// Range check performed internally by c-kzg-4844 library during deserialization

// The type-3 transaction blob data field element range validation occurs at the execution layer,
// not in the beacon chain consensus code. The beacon-chain code operates on pre-validated
// KZG commitments received via the signed block body. The C-KZG library handles deserialization
// and field element range validation within VerifyCellKZGProofBatch.
func VerifyCellKZGProofBatch(commitmentsBytes []Bytes48, cellIndices []uint64, cells []Cell, proofsBytes []Bytes48) (bool, error) {
	ckzgCells := make([]ckzg4844.Cell, len(cells))
	for i := range cells {
		ckzgCells[i] = ckzg4844.Cell(cells[i])
	}
	return ckzg4844.VerifyCellKZGProofBatch(commitmentsBytes, cellIndices, ckzgCells, proofsBytes)
}

